def top_k_frequent(nums, k):
    # Create a dictionary to store the frequency of each number
    freq = {}
    for num in nums:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Create a min heap to store the top k frequent numbers
    heap = []
    for num in freq:
        if len(heap) < k:
            heapq.heappush(heap, (freq[num], num))
        else:
            if freq[num] > heap[0][0]:
                heapq.heappop(heap)
                heapq.heappush(heap, (freq[num], num))

    # Extract the top k frequent numbers from the heap
    top_k = []
    while heap:
        top_k.append(heapq.heappop(heap)[1])
    return top_k

