def max_path_sum(triangle, n, m):
    # Base case
    if n == 1:
        return triangle[0][0]
    if n == 2:
        return max(triangle[0][0], triangle[1][0])
    # Recursive case
    return max(triangle[n-1][0] + max_path_sum(triangle, n-1, m), 
               triangle[n-1][m-1] + max_path_sum(triangle, n-1, m-1))

