    if month == 1 or month == 3 or month == 5 or month == 7 or month == 8 or month == 10 or month == 12:
        return True
    else:
        return False

def reverse_string_list(string_list):
    reversed_list = []
    for string in string_list:
        reversed_list.insert(0, string)
    return reversed_list

def Find_Min(lst):
    min_len = len(lst[0])
    min_sublist = []
    for sublist in lst:
        if len(sublist) < min_len:
            min_len = len(sublist)
            min_sublist = sublist
    return min_sublist

