def upper_ctr(s):
    ctr = 0
    for c in s:
        if c.isupper():
            ctr += 1
    return ctr

def combinations_list(lst):
    result = []
    for i in range(len(lst)):
        for j in range(i+1, len(lst)+1):
            result.append(lst[i:j])
    return result

def max_subarray_product(arr):
    max_product = float('-inf')
    current_product = 1
    for num in arr:
        current_product *= num
        max_product = max(max_product, current_product)
        if current_product == 0:
            current_product = 1
    return max_product

def check_value(dictionary, value):
    for key in dictionary:
        if dictionary[key] != value:
            return False
    return True

def find_peak(arr):
    n = len(arr)
    if n == 0:
        return None
    if n == 1:
        return arr[0]
    if n == 2:
        return max(arr)
    mid = n // 2
    if arr[mid] > arr[mid - 1] and arr[mid] > arr[mid + 1]:
        return arr[mid]
    elif arr[mid] < arr[mid - 1]:
        return find_peak(arr[:mid])
    else:
        return find_peak(arr[mid + 1:])

def decimal_to_Octal(n):
    octal = ""
    while n > 0:
        octal = str(n % 8) + octal
        n = n // 8
    return octal

def max_product(arr, n):
    max_product = 0
    for i in range(n):
        for j in range(i+1, n):
            product = arr[i] * arr[j]
            if product > max_product:
                max_product = product
    return max_product

def max_profit(stock_prices, k):
    if k == 0 or len(stock_prices) == 0:
        return 0
    profit = 0
    for i in range(len(stock_prices)):
        for j in range(i+1, len(stock_prices)):
            profit = max(profit, stock_prices[j] - stock_prices[i])
    return profit

def add_pairwise(tuples):
    result = []
    for i in range(len(tuples)):
        for j in range(i+1, len(tuples)):
            result.append(tuples[i] + tuples[j])
    return result

def check_Consecutive(lst):
    for i in range(len(lst)-1):
        if lst[i+1] - lst[i] != 1:
            return False
    return True

def tuple_intersection(tuples):
    result = set()
    for tup in tuples:
        for i in range(len(tup)):
            for j in range(i+1, len(tup)):
                result.add(tuple(tup[i], tup[j]))
    return result

