import re

def match(string):
    pattern = r'[A-Z][a-z]+'
    return bool(re.search(pattern, string))

def first_Factorial_Divisible_Number(x):
    for i in range(1, x+1):
        if factorial(i) % x == 0:
            return i
    return None

def factorial(n):
    if n == 0:
        return 1
    else:
        return n * factorial(n-1)

def largest_palindrome(arr):
    largest = 0
    for num in arr:
        if str(num) == str(num)[::-1]:
            if num > largest:
                largest = num
    return largest

def binomial_probability(n, k, p):
    """
    Compute binomial probability for the given number.
    """
    return (p**k) * ((1-p)**(n-k))

def frequency_Of_Largest(arr):
    max_val = max(arr)
    return arr.count(max_val)

def extract_symmetric(tuples):
    result = set()
    for i in range(len(tuples)):
        for j in range(i+1, len(tuples)):
            if tuples[i] == tuples[j]:
                result.add((tuples[i], tuples[j]))
    return result

def sum_gp(a, r, n):
    if n == 1:
        return a
    else:
        return a + r * sum_gp(a, r, n-1)

def binary_search(arr, target):
    low = 0
    high = len(arr) - 1

    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return True
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return False

def calculate_polygons(x, y, width, height, step):
    polygons = []
    for i in range(0, width, step):
        for j in range(0, height, step):
            polygons.append([(x + i * step, y + j * step), (x + i * step, y + j * step + 1), (x + i * step + 1, y + j * step), (x + i * step + 1, y + j * step + 1)])
    return polygons

import re

def remove_lowercase(string):
