def heap_queue_smallest(numbers, k):
    heap = []
    for num in numbers:
        heappush(heap, num)
    result = []
    for _ in range(k):
        result.append(heappop(heap))
    return result

def gcd(a, b):
    if b == 0:
        return a
    else:
        return gcd(b, a % b)

def concatenate_elements(elements):
    result = ''
    for element in elements:
        result += element
    return result

def num_comm_div(a, b):
    if a == 0 or b == 0:
        return 0
    else:
        return num_comm_div(b, a % b)

def add_consecutive_nums(nums):
    result = []
    for i in range(len(nums)):
        if i == 0:
            result.append(nums[i])
        else:
            result.append(nums[i] + result[i-1])
    return result

def sum_of_series(n):
    return (n * (n + 1) * (2 * n + 1)) // 6

